tool_calls.arguments:
{"command":"# Patch the deployment to add an emptyDir volume and mount it to /mnt/data.
kubectl patch deployment app --type='json' -p='[
  {"op": "add", "path": "/spec/template/spec/volumes/0", "value": {"name": "writable-data", "emptyDir": {}}}
]'

kubectl patch deployment app --type='json' -p='[
  {"op": "add", "path": "/spec/template/spec/containers/0/volumeMounts/0", "value": {"name": "writable-data", "mountPath": "/mnt/data"}}
]'

# Check the status of the rollout
kubectl rollout status deployment app
"}

